param([Parameter(Mandatory)][string]$OutputPath,[string]$ReferencePath=(Join-Path $PSScriptRoot '../../../planning/stage-2/repos/dotj-core/evidence/unicode-replacement-edge-contract-v10.0.12.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
function Failure-Of($ErrorRecord){$e=$ErrorRecord.Exception;while($e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$r.unknown=[int]$e.CharUnknown;$r.index=$e.Index;$r.high=[int]$e.CharUnknownHigh;$r.low=[int]$e.CharUnknownLow;$r.isPair=$e.IsUnknownSurrogate()};if($e -is [Text.DecoderFallbackException]){$r.bytesUnknown=[int[]]$e.BytesUnknown;$r.index=$e.Index};return $r}

if($null -eq [Text.Encoding].GetMethod('GetBytes',[type[]]@([string],[int],[int]))){throw 'Pinned public GetBytes string-range allocation signature is absent'}
$reference=Get-Content -LiteralPath $ReferencePath -Raw|ConvertFrom-Json;if($reference.totalCases -ne 40320 -or $reference.runtimeVersion -ne '10.0.12' -or $reference.coreLibSha256 -ne $coreHash){throw 'Complete pinned replacement reference required'}
$profiles=[Collections.Generic.List[object]]::new();$total=0;$operations=@('CountArray','CountString','BytesArrayRange','BytesArrayWhole','BytesStringRange','BytesStringWhole')
foreach($profile in $reference.profiles){Write-Output ("START returned encoder allocations profile="+$profiles.Count);$owner=[Text.Encoding]([Text.UnicodeEncoding]::new([bool]$profile.bigEndian,$true,$false)).Clone();$owner.EncoderFallback=[Text.EncoderReplacementFallback]::new([string]::new([char[]][int[]]$profile.replacement));$rows=[Collections.Generic.List[object]]::new();$seen=[Collections.Generic.HashSet[string]]::new()
 foreach($entry in $profile.rows){if($entry.status -ne 'RETURNED' -or -not $entry.row.encode -or $entry.row.stateful -or -not $entry.row.countBefore){continue};$r=$entry.row;$key=([int[]]$r.source)-join ',';if(-not $seen.Add($key)){continue};$visible=[char[]][int[]]$r.source;$source=[char[]](@(56320)+[int[]]$r.source+@(55296));$text=[string]::new($source);$visibleText=[string]::new($visible);$start=1;$count=$visible.Length;$results=[ordered]@{}
  foreach($operation in $operations){try{$value=switch($operation){'CountArray'{$owner.GetByteCount($source,$start,$count)};'CountString'{$owner.GetByteCount($visibleText)};'BytesArrayRange'{,[int[]]$owner.GetBytes($source,$start,$count)};'BytesArrayWhole'{,[int[]]$owner.GetBytes($visible)};'BytesStringRange'{,[int[]]$owner.GetBytes($text,$start,$count)};'BytesStringWhole'{,[int[]]$owner.GetBytes($visibleText)}};$results[$operation]=[ordered]@{ok=$true;value=$value}}catch{$results[$operation]=Failure-Of $_}}
  $rows.Add([ordered]@{basisCaseId=$entry.caseId;source=[int[]]$source;start=$start;count=$count;referenceCountResult=$r.countResult;results=$results});$total++
 };$profiles.Add([ordered]@{bigEndian=$profile.bigEndian;replacement=[int[]]$profile.replacement;rows=$rows.ToArray()})
}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();inputSha256=(Get-FileHash -LiteralPath $ReferencePath -Algorithm SHA256).Hash.ToLowerInvariant();selectedKnownReturnedStatelessCountContexts=$total;unselectedStatelessSourceContexts=144-$total;operations=$operations;profiles=$profiles.ToArray();qualification='NATIVE_STATELESS_ENCODER_ALLOCATIONS_FOR_SELECTED_KNOWN_RETURNED_COUNT_CONTEXTS_ONLY; UNSELECTED_NATIVE_NO_RETURN_CONTEXTS_UNQUALIFIED; NO_JAVA_OR_TASK_ACCEPTANCE'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 19 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS returned encoder allocation capture: $total selected count contexts"
